import * as React from "react";

export type NoteSquareIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function NoteSquareIcon({ size = 20, ...props }: NoteSquareIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <rect x="4" y="4" width="16" height="16" rx="2" /><path d="M10.5 15.5V9.5L15 8v6" />
    </svg>
  );
}
